import{_ as a,o as r,c as t,a3 as i}from"./chunks/framework.CJlOecQn.js";const h=JSON.parse('{"title":"رخصة الإقامة والبطاقة الشخصية","description":"كيف تحصل على أول رخصة إقامة والبطاقة الشخصية، وكيف تجددها، وما يحدث عند انتهائها، وقواعد المغادرة والعودة.","frontmatter":{"title":"رخصة الإقامة والبطاقة الشخصية","description":"كيف تحصل على أول رخصة إقامة والبطاقة الشخصية، وكيف تجددها، وما يحدث عند انتهائها، وقواعد المغادرة والعودة.","lastChecked":"2026-10","sourceCount":11},"headers":[],"relativePath":"ar/guide/residence-permit-and-qid.md","filePath":"ar/guide/residence-permit-and-qid.md"}'),s={name:"ar/guide/residence-permit-and-qid.md"};function f(o,e,n,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="رخصة-الإقامة-والبطاقة-الشخصية" tabindex="-1">رخصة الإقامة والبطاقة الشخصية <a class="header-anchor" href="#رخصة-الإقامة-والبطاقة-الشخصية" aria-label="Permalink to &quot;رخصة الإقامة والبطاقة الشخصية&quot;">​</a></h1><p>إذا قدمت للإقامة في قطر، فإنك تصل بسمة إقامة ثم تتقدم للحصول على أول رخصة إقامة. وتتولى وزارة الداخلية ذلك عبر خدمة رخصة الإقامة لأول مرة، ويوقّع نموذج الطلب كفيلك، سواء كان شركة أو فردًا.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>تُحتسب رسوم البطاقة الشخصية مع رخصة الإقامة وبحسب مدة صلاحيتها.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="كيف-تحصل-على-أول-رخصة-إقامة" tabindex="-1">كيف تحصل على أول رخصة إقامة <a class="header-anchor" href="#كيف-تحصل-على-أول-رخصة-إقامة" aria-label="Permalink to &quot;كيف تحصل على أول رخصة إقامة&quot;">​</a></h2><ol><li>أجرِ الفحص الطبي خلال ثلاثين يومًا من دخولك إلى قطر.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></li><li>أكمل إجراء البصمة بعد إتمام الفحص الطبي.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li>جهّز المستندات الخاصة بنوع كفالتك، وهي مذكورة أدناه.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>قدّمها في مراكز خدمات وزارة الداخلية أو إدارة شؤون الوافدين.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li></ol><h3 id="مستندات-كفالة-الشركات" tabindex="-1">مستندات كفالة الشركات <a class="header-anchor" href="#مستندات-كفالة-الشركات" aria-label="Permalink to &quot;مستندات كفالة الشركات&quot;">​</a></h3><ul><li>عقد العمل مصدقًا من إدارة العمل.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>نموذج طلب رخصة الإقامة مطبوعًا وموقعًا من الكفيل.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>جواز سفرك الأصلي وصورتك الشخصية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>صورة من بطاقة المنشأة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>شهادة فصيلة الدم.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li></ul><h3 id="مستندات-الكفالة-الشخصية" tabindex="-1">مستندات الكفالة الشخصية <a class="header-anchor" href="#مستندات-الكفالة-الشخصية" aria-label="Permalink to &quot;مستندات الكفالة الشخصية&quot;">​</a></h3><ul><li>نموذج طلب رخصة الإقامة مطبوعًا وموقعًا من الكفيل.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li><li>جواز السفر الأصلي وصورة شخصية للمكفول.<sup class="footnote-ref"><a href="#fn1" id="fnref1:10">[1]</a></sup></li><li>شهادة فصيلة الدم.<sup class="footnote-ref"><a href="#fn1" id="fnref1:11">[1]</a></sup></li></ul><p>الرسوم الحالية مذكورة في صفحة وزارة الداخلية نفسها.<sup class="footnote-ref"><a href="#fn1" id="fnref1:12">[1]</a></sup></p><h2 id="كيف-تجدد-رخصة-الإقامة" tabindex="-1">كيف تجدد رخصة الإقامة <a class="header-anchor" href="#كيف-تجدد-رخصة-الإقامة" aria-label="Permalink to &quot;كيف تجدد رخصة الإقامة&quot;">​</a></h2><ul><li>تحتاج إلى نموذج التجديد موقعًا ومختومًا من الكفيل، وجواز السفر الأصلي، وبطاقة المنشأة للشركة أو البطاقة الشخصية للكفيل الفرد، وتُسدد في هذه المرحلة رسوم تصريح العمل ورخصة الإقامة.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>يمكنك التجديد في إدارة شؤون الوافدين أو مراكز خدمات وزارة الداخلية، والخدمة متاحة أيضًا عبر تطبيق مطراش2 وبوابة الخدمات الإلكترونية للوزارة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li><li>تذكر الوزارة أن التجديد لمدة 3 سنوات يمنح خصمًا بنسبة 20% من الرسوم.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li>لمتابعة التجديد، استخدم خدمة تتبع تجديد رخصة الإقامة بالرقم الشخصي للكفيل أو لحامل الرخصة.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li>لمعرفة تواريخ انتهاء مستنداتك، تغطي صفحة الاستعلامات الأخرى البطاقة الشخصية وجواز السفر ورخصة الإقامة ورخصة القيادة.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ul><h2 id="إذا-انتهت-رخصة-الإقامة" tabindex="-1">إذا انتهت رخصة الإقامة <a class="header-anchor" href="#إذا-انتهت-رخصة-الإقامة" aria-label="Permalink to &quot;إذا انتهت رخصة الإقامة&quot;">​</a></h2><p>تذكر وزارة الداخلية أن رخصة الإقامة المنتهية يجب تجديدها خلال 90 يومًا، وبعدها تُفرض غرامة يومية بحد أقصى، والمبالغ مذكورة في صفحة الإرشادات.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></p><h2 id="المستندات-المفقودة-أو-التالفة-أو-المتغيرة" tabindex="-1">المستندات المفقودة أو التالفة أو المتغيرة <a class="header-anchor" href="#المستندات-المفقودة-أو-التالفة-أو-المتغيرة" aria-label="Permalink to &quot;المستندات المفقودة أو التالفة أو المتغيرة&quot;">​</a></h2><ul><li>عند فقدان البطاقة، تدرج الوزارة خدمة بلاغ الفقد ضمن خدمات الوثائق الرسمية.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>تتضمن صفحة الاستعلامات الأخرى نموذج طلب البطاقة الذكية للمقيمين، ويمكنك تعبئته وطباعته.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>إذا حصلت على جواز جديد لأن القديم انتهى أو فُقد أو تلف، فهناك خدمة لتحديث بياناتك. أحضر الجوازين القديم والجديد ونموذج الطلب، مع بلاغ الفقد إذا كان الجواز مفقودًا. والخدمة متاحة عبر تطبيق مطراش2 ومراكز خدمات وزارة الداخلية ومقر إدارة الجوازات.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></li></ul><h2 id="المغادرة-والعودة" tabindex="-1">المغادرة والعودة <a class="header-anchor" href="#المغادرة-والعودة" aria-label="Permalink to &quot;المغادرة والعودة&quot;">​</a></h2><ul><li>توفر الوزارة خدمة مجانية لإشعار المغادرة للوافدين الذين يغادرون البلاد في إجازة، وهي متاحة عبر بوابة الخدمات الإلكترونية وتطبيق مطراش2 ومراكز الخدمات.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li>تتيح صفحة تصاريح الخروج والدخول الاستعلام عن تاريخ انتهاء إشعار المغادرة.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></li><li>إذا بقيت خارج قطر أكثر من 6 أشهر، فإنك تحتاج إلى سمة عودة، ويشترط أن تكون رخصة إقامتك سارية. ويقدم الكفيل الطلب عبر مطراش2 أو بوابة الخدمات الإلكترونية أو إدارة شؤون الوافدين أو مراكز الخدمات.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li></ul><h2 id="إلغاء-رخصة-الإقامة" tabindex="-1">إلغاء رخصة الإقامة <a class="header-anchor" href="#إلغاء-رخصة-الإقامة" aria-label="Permalink to &quot;إلغاء رخصة الإقامة&quot;">​</a></h2><p>لإلغاء رخصة الإقامة، توقّع أنت وكفيلك نموذج الطلب، ويلزم إبراز البطاقة الشخصية للكفيل أو بطاقة المنشأة للتحقق من التوقيع. ويمكن إتمام ذلك أيضًا عبر مطراش2 وبوابة الخدمات الإلكترونية.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></p><h2 id="متابعة-الطلب" tabindex="-1">متابعة الطلب <a class="header-anchor" href="#متابعة-الطلب" aria-label="Permalink to &quot;متابعة الطلب&quot;">​</a></h2><p>استخدم صفحة الاستعلام عن رخص الإقامة لمتابعة طلبك برقم التأشيرة، أو بالرقم الشخصي للكفيل أو الوكيل أو الشخص المفوض. وفي الصفحة نفسها خدمة الاستعلام عن طلب تغيير جهة العمل.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></p><p>انظر أيضًا: <a href="./arriving-and-visas">الوصول والتأشيرات</a>، <a href="./metrash">مطراش</a>، <a href="./family-visas">التأشيرات العائلية</a>، <a href="./work-and-labour-rights">العمل وحقوق العمال</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fyttyrttt" target="_blank" rel="noreferrer">رخصة الإقامة لأول مرة (First Time Residence Permit)</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:10" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:11" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:12" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/47" target="_blank" rel="noreferrer">نصائح وإرشادات (Tips &amp; Guidelines)</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fegama1" target="_blank" rel="noreferrer">تجديد رخصة الإقامة (Residence Permit Renewal)</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/residencypermits" target="_blank" rel="noreferrer">الاستعلام عن رخص الإقامة (Residency Permits inquiry)</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/others" target="_blank" rel="noreferrer">استعلامات أخرى (Other Inquiries)</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?docId=a96cc4f1-23a6-4693-ae9e-179555192762&amp;viewType=CATEGORY" target="_blank" rel="noreferrer">خدمات الوثائق الرسمية (Official Documents Services)</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fiuytro" target="_blank" rel="noreferrer">تغيير بيانات الجواز (Changing Passport information)</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn8" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fvisa%2Bcomplaints%2Fw456" target="_blank" rel="noreferrer">إشعار المغادرة (Leave Notification)</a>. آخر تحقق: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn9" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/exitservices" target="_blank" rel="noreferrer">تصاريح الخروج والدخول (Exit &amp; Entry Permits)</a>. آخر تحقق: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn10" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Freturn%2Bvisas%2Fvisa0127" target="_blank" rel="noreferrer">سمة العودة لمن بقي خارج البلاد أكثر من 6 أشهر (Return Visa)</a>. آخر تحقق: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn11" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fxcdsa" target="_blank" rel="noreferrer">إلغاء رخصة الإقامة (Cancellation of Residence Permit)</a>. آخر تحقق: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',26)])])}const m=a(s,[["render",f]]);export{h as __pageData,m as default};
